import json, sys

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception:
            continue
        t = d.get('type')
        ts = d.get('timestamp', '')
        if t not in ('user', 'assistant'):
            continue
        msg = d.get('message', {})
        role = msg.get('role')
        content = msg.get('content')
        if isinstance(content, str):
            print(f'--- {role} [{ts}] ---')
            print(content[:800])
        elif isinstance(content, list):
            for c in content:
                if not isinstance(c, dict):
                    continue
                ctype = c.get('type')
                if ctype == 'text':
                    txt = c.get('text', '')
                    if txt.strip():
                        print(f'--- {role} text [{ts}] ---')
                        print(txt[:800])
                elif ctype == 'tool_use':
                    print(f'--- {role} tool_use: {c.get("name")} [{ts}] ---')
                    print(json.dumps(c.get('input', {}))[:250])
                elif ctype == 'tool_result':
                    cont = c.get('content')
                    if isinstance(cont, list):
                        s = ' '.join(x.get('text','') for x in cont if isinstance(x, dict))
                    else:
                        s = str(cont)
                    if c.get('is_error'):
                        print(f'--- {role} tool_result ERROR [{ts}] ---')
                    print(str(s)[:250])

