// A directory's declared checks — `<dir>/declared-checks.json`, compiled by the
// pattern-check engine. The declaration file gates the import: a tree with no
// declarations never reaches for the checks helpers, so the loader keeps working
// wherever only the pack machinery is present. A broken declaration is reported
// like a broken manifest, never thrown — the neighbouring coded rules still run.
const DECLARED_CHECKS_FILE = 'declared-checks.json';
async function declaredChecksIn(dir, label, errors) {
  if (!existsSync(join(dir, DECLARED_CHECKS_FILE))) return [];
  try {
    const { loadDeclaredChecks } = await import('../checks/helpers/pattern-rules.mjs');
    return loadDeclaredChecks(dir);
  } catch (e) {
    errors.push({ what: `the declared checks in ${label} failed to load: ${e.message}`, fix: `fix ${DECLARED_CHECKS_FILE} in ${label}`, dir });
    return [];
  }
}

// One scope's coded rules, imported in filename order. Isolated per module for
// the reason a manifest's own import was not: a manifest that failed to import
// took the whole pack with it, where a rule module that does is now one reported
// fault beside its working neighbours. A module exporting no rule is the same
// class of fault — a file sitting in the directory contributing nothing is what
// this reports rather than silently drops.
async function ruleModulesIn(packDir, scope, label, errors) {
  const rules = [];
  for (const file of ruleModuleFiles(packDir, scope)) {
    const name = `${scope}/${basename(file)}`;
    let rule;
    try {
      rule = (await import(pathToFileURL(file).href)).default;
    } catch (e) {
      errors.push({ what: `${label}/${name} failed to load: ${e.message}`, fix: `fix ${name}, or remove it from the pack`, dir: packDir });
      continue;
